    track.motion_length = d;
    true
}

pub(crate) fn resolve_motion_path(
    source: &[u8],
    tokens: &[XmlToken],
    animation: usize,
) -> Option<XmlSpan> {
    if let Some(direct) = attr(source, tokens, animation, b"path") {
        return Some(direct);
    }
    let depth = tokens.get(animation)?.depth;
    let mut mp = None;
    for (i, t) in tokens.iter().enumerate().skip(animation + 1) {
        if t.kind == TokenKind::EndElement && t.depth == depth {
            break;
        }
        if t.depth == depth + 1
            && matches!(t.kind, TokenKind::StartElement | TokenKind::EmptyElement)
            && t.prefix.length == 0
            && t.local_name.slice(source) == Some(b"mpath")
        {
            mp = Some(i);
            break;
        }
    }
    let m = mp?;
    let href = tokens
        .iter()
        .skip(m + 1)
        .take_while(|t| t.kind == TokenKind::Attribute)
        .find(|t| {
            t.local_name.slice(source) == Some(b"href")
                && (t.prefix.length == 0 || t.prefix.slice(source) == Some(b"xlink"))
        })?
        .value;
    let value = href.slice(source)?;
    if value.len() < 2 || value[0] != b'#' {
        return None;
    }
    let id = &value[1..];
    let mut found = None;
    for (i, t) in tokens.iter().enumerate() {
        if !matches!(t.kind, TokenKind::StartElement | TokenKind::EmptyElement)
            || t.prefix.length != 0
            || t.local_name.slice(source) != Some(b"path")
        {
            continue;
        }
        if attr(source, tokens, i, b"id").and_then(|s| s.slice(source)) == Some(id) {
            if found.is_some() {
                return None;
            }
            found = attr(source, tokens, i, b"d")
        }
    }
    found
}
